@Controller('orders')
@UseGuards(AuthGuard('jwt'))
export class OrderReturnController {
  constructor(private readonly orderService: OrderService) {}

  @Post(':orderId/return-request')
  async requestReturn(
    @Param('orderId') orderId: string,
    @Body() dto: CreateReturnDto,
    @CurrentUser() user: UserEntity,
  ) {
    const order = await this.orderService.findCustomerOrder(orderId, user.id);
    if (!order) throw new ForbiddenException('Order does not belong to the current customer');
    return await this.orderService.createReturnTicket(order.id, dto.items, dto.reason);
  }
}
